import forgelib as F
G = F.make(slug="the-forge-pickaxe-progression", order=18, kw="best pickaxe in the forge",
 title="Best Pickaxe in The Forge: Upgrade Order, Island 1 to 4",
 h1="Best Pickaxe in The Forge: The Full Upgrade Path from Island 1 to Island 3 (and Beyond)",
 desc="The best pickaxe in The Forge at every stage: the community upgrade order from Iron to Yin-Yang, which pickaxes to skip, and stats and prices for the top ones.",
 kw2=["the forge pickaxe order","the forge pickaxe tier list","the forge pickaxe upgrade guide","how to get to island 3 fast the forge","the forge pickaxes"],
 related=["the-forge-prismatic-pickaxe","the-forge-heavenly-pickaxe","the-forge-dragon-head-pickaxe","the-forge-runes-guide"],
 ids=["y-wxdCsdJEg"],
 lead="Your pickaxe decides which rocks you can break, so choosing the <strong>best pickaxe in The Forge</strong> at each stage is the fastest way to progress. Fridge's full upgrade video takes you from Island 1 to Island 3. This page follows the same path with the Forge Wiki's current order and prices.",
 heading="Watch Fridge's Pickaxe Upgrade Guide",
 sections=[
 ("stats","How Pickaxe Stats Work","""<p>Each pickaxe has <strong>Mine Power</strong> (damage per swing), <strong>Mine Speed</strong>, <strong>Luck Boost</strong> and <strong>Rune Slots</strong>. Some rocks require a minimum Mine Power. For example, Volcanic Rocks need 100. Rarity runs from Common Stone up to Mythic Dragon Head and the Heavenly Pickaxe.</p>"""),
 ("order","The Pickaxe Upgrade Order","""<div class="table-wrap"><table><caption>Recommended pickaxe order (Forge Wiki community guide)</caption><thead><tr><th scope="col">#</th><th scope="col">Pickaxe</th><th scope="col">Where</th></tr></thead><tbody>
<tr><td>1</td><td>Iron Pickaxe</td><td>World 1 shop (Miner Fred)</td></tr><tr><td>2</td><td>Stonewake's Pickaxe</td><td>Stonewake's Cross Inner Cave, 3,333 Gold</td></tr>
<tr><td>3</td><td>Cobalt Pickaxe</td><td>World 2 shop</td></tr><tr><td>4</td><td>Mythril Pickaxe</td><td>World 2 shop</td></tr><tr><td>5</td><td>Lightite Pickaxe</td><td>World 2 shop</td></tr>
<tr><td>6</td><td>Demonic Pickaxe</td><td>Skal's quest, Volcanic Depths</td></tr><tr><td>7</td><td>Snow Pickaxe</td><td>World 3 shop</td></tr><tr><td>8</td><td>Void Pickaxe</td><td>World 3 shop</td></tr>
<tr><td>9</td><td>Holy Pickaxe</td><td>World 4 shop</td></tr><tr><td>10</td><td>Yin-Yang Pickaxe</td><td>Jade Cave</td></tr></tbody></table></div>"""),
 ("island1","Island 1 to Island 2","""<p>Buy the Iron Pickaxe, then grab the <strong>Stonewake's Pickaxe</strong> (33 Mine Power, +10% Luck, 3 slots). Pro Game Guides suggests buying the Gold Pickaxe last and skipping the Platinum, because the Stonewake's is cheaper and better. The Forgotten Kingdom opens at <strong>level 10</strong> after Sensei Moro's questline. The <strong>Arcane Pickaxe</strong> (115 Mine Power, +50% Luck, 125,000 Gold) from the Bard quest is an option on Island 2, but the wiki now considers it outclassed. See our <a href="the-forge-bard-quest.html">Bard quest guide</a>.</p>"""),
 ("island2","Island 2 to Island 3","""<p>On the Forgotten Kingdom, buy Cobalt, then Mythril, then Lightite from Miner Fred. The <strong>Demonic Pickaxe</strong> (200 Mine Power, +53% Luck) is behind Skal's quest in the Volcanic Depths. Pro Game Guides suggests skipping the Magma Pickaxe for its price. The Frostspire Expanse opens at <strong>level 70+</strong>, which is the \"get to Island 3 fast\" goal in Fridge's video. Some Frostspire shop pickaxes, from the Mist Pickaxe up, also need specific Sensei Moro quests done.</p>"""),
 ("island3","Island 3 Endgame Pickaxes","""<div class="table-wrap"><table><caption>Top Frostspire pickaxes (Forge Wiki)</caption><thead><tr><th scope="col">Pickaxe</th><th scope="col">Mine Power</th><th scope="col">Luck</th><th scope="col">Cost</th><th scope="col">How</th></tr></thead><tbody>
<tr><td><a href="the-forge-prismatic-pickaxe.html">Prismatic</a></td><td>650</td><td>+72%</td><td>1.5M</td><td>Iceberg, Mosasaursit</td></tr>
<tr><td><a href="the-forge-heavenly-pickaxe.html">Heavenly</a></td><td>725</td><td>+85%</td><td>2M</td><td>Secret Maze quests</td></tr>
<tr><td><a href="the-forge-dragon-head-pickaxe.html">Dragon Head</a></td><td>750</td><td>+78%</td><td>2.2M</td><td>Raven and Cult quests</td></tr></tbody></table></div>
<p>After that, the Crimson Sakura Isles (Island 4, February 2026) add the Holy and Yin-Yang pickaxes at the end of the wiki's list. Rune every pickaxe you plan to keep. See our <a href="the-forge-runes-guide.html">runes guide</a>.</p>""")],
 faq=[("What is the best pickaxe in The Forge?","For Island 3, the Dragon Head Pickaxe has the most Mine Power (750). The Forge Wiki's full route ends with the Holy and Yin-Yang pickaxes on Island 4."),
      ("What pickaxe should I buy first in The Forge?","The Iron Pickaxe, then the Stonewake's Pickaxe in the Stonewake's Cross Inner Cave for 3,333 Gold."),
      ("What level do you need for Island 3 in The Forge?","Level 70 or higher, according to Pro Game Guides.")],
 sources=[F.wiki("Pickaxe","Pickaxes"),F.wiki("Guide","Community guide: pickaxe progression"),F.wiki("Stonewake%27s_Pickaxe","Stonewake's Pickaxe"),F.wiki("Arcane_Pickaxe","Arcane Pickaxe"),F.wiki("Demonic_Pickaxe","Demonic Pickaxe"),("Pro Game Guides: The Forge island level requirements","https://progameguides.com/roblox/the-forge-map-all-islands-locations-level-requirements/")])
